// Make this file safe to import in a non-Civ7 environment by mocking out GameInfo if it doesn't exist.
/* eslint-disable @typescript-eslint/no-explicit-any */
if (typeof GameInfo === "undefined") {
	const dummyEntry = new Proxy(
		{},
		{
			get() {
				return -1;
			},
		},
	);
	const dummyTable = new Proxy([] as any, {
		get(target, prop) {
			if (prop === "find") return () => dummyEntry;
			return (target as any)[prop];
		},
	});
	(globalThis as any).GameInfo = new Proxy({} as any, {
		get() {
			return dummyTable;
		},
	});
}
/* eslint-enable @typescript-eslint/no-explicit-any */

export const g_MountainTerrain: TerrainType = GameInfo.Terrains.find(
	(t) => t.TerrainType == "TERRAIN_MOUNTAIN",
)!.$index;
export const g_HillTerrain: TerrainType = GameInfo.Terrains.find((t) => t.TerrainType == "TERRAIN_HILL")!.$index;
export const g_FlatTerrain: TerrainType = GameInfo.Terrains.find((t) => t.TerrainType == "TERRAIN_FLAT")!.$index;
export const g_CoastTerrain: TerrainType = GameInfo.Terrains.find((t) => t.TerrainType == "TERRAIN_COAST")!.$index;
export const g_OceanTerrain: TerrainType = GameInfo.Terrains.find((t) => t.TerrainType == "TERRAIN_OCEAN")!.$index;
export const g_NavigableRiverTerrain: TerrainType = GameInfo.Terrains.find(
	(t) => t.TerrainType == "TERRAIN_NAVIGABLE_RIVER",
)!.$index;

export const g_TundraBiome: BiomeType = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_TUNDRA")!.$index;
export const g_GrasslandBiome: BiomeType = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_GRASSLAND")!.$index;
export const g_PlainsBiome: BiomeType = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_PLAINS")!.$index;
export const g_TropicalBiome: BiomeType = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_TROPICAL")!.$index;
export const g_DesertBiome: BiomeType = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_DESERT")!.$index;
export const g_MarineBiome: BiomeType = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_MARINE")!.$index;

export const g_VolcanoFeature: FeatureType = GameInfo.Features.find((t) => t.FeatureType == "FEATURE_VOLCANO")!.$index;

let temp;
export let g_GrasslandLatitude = 0;
export let g_PlainsLatitude = 0;
export let g_DesertLatitude = 0;
export let g_TropicalLatitude = 0;
temp = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_GRASSLAND")!.MaxLatitude;
if (temp) g_GrasslandLatitude = temp;
temp = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_PLAINS")!.MaxLatitude;
if (temp) g_PlainsLatitude = temp;
temp = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_DESERT")!.MaxLatitude;
if (temp) g_DesertLatitude = temp;
temp = GameInfo.Biomes.find((t) => t.BiomeType == "BIOME_TROPICAL")!.MaxLatitude;
if (temp) g_TropicalLatitude = temp;

